/**
 * A tiny script for the page's <head>. It applies the saved theme before the
 * first paint, so a refresh never flashes the wrong background. First-time
 * visitors get the default theme (dark). Unavailable storage is ignored.
 *
 * Plain strings only, so it can be imported from a server component.
 */
export function themeInitScript(options: {
  storageKey: string;
  colors: { light: string; dark: string };
}): string {
  const key = JSON.stringify(options.storageKey);
  const colors = JSON.stringify(options.colors);
  return (
    `(function(){var t='dark';` +
    `try{var v=localStorage.getItem(${key});if(v==='light'||v==='dark')t=v}catch(e){}` +
    `document.documentElement.setAttribute('data-theme',t);` +
    `var m=document.querySelector('meta[name="theme-color"]');` +
    `if(m)m.setAttribute('content',${colors}[t])})()`
  );
}

'use client';

import { useEffect, useRef, useSyncExternalStore } from 'react';
import { revealDocument } from './circle-reveal';
import type { SiteTheme, Theme } from './site-theme';
import { MoonIcon, SunIcon } from './theme-icons';
import './theme-transition-panel.css';

/** The theme on screen, kept in step with the store on every render. */
export function useSiteTheme(store: SiteTheme): Theme {
  // The server and the first client render use the default so they agree.
  return useSyncExternalStore(store.subscribe, store.get, () => 'dark');
}

export interface ThemeToggleProps {
  theme: Theme;
  /**
   * Called at the moment the new theme should take effect, inside the reveal.
   * It should switch the theme synchronously (see createSiteTheme).
   */
  onThemeChange: (theme: Theme) => void | Promise<void>;
  className?: string;
}

/**
 * A sun/moon button that reveals the new theme across the whole page as a
 * circle growing from the button. It shows the action that is available: the
 * sun while dark, the moon while light.
 *
 * Fast repeated clicks are handled in order: the last click decides the final
 * theme, each step finishes before the next starts, and the button is never
 * disabled, so keyboard focus stays where it was.
 */
export function ThemeToggle({
  theme,
  onThemeChange,
  className = '',
}: ThemeToggleProps) {
  const button = useRef<HTMLButtonElement>(null);
  const shown = useRef(theme);
  const wanted = useRef(theme);
  const busy = useRef(false);
  shown.current = theme;

  useEffect(() => {
    // Follow outside changes (another tab) while nothing is animating.
    if (!busy.current) wanted.current = theme;
  }, [theme]);

  const click = async () => {
    wanted.current = wanted.current === 'dark' ? 'light' : 'dark';
    if (busy.current) return; // the running loop picks up the latest wish
    busy.current = true;
    let applied = shown.current;
    try {
      while (applied !== wanted.current) {
        const goal = wanted.current;
        applied = goal;
        await revealDocument(() => onThemeChange(goal), button.current);
      }
    } finally {
      busy.current = false;
      wanted.current = applied;
    }
  };

  return (
    <button
      ref={button}
      type='button'
      className={`mg-theme-btn ${className}`}
      aria-label={
        theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme'
      }
      onClick={click}
    >
      {theme === 'dark' ? <SunIcon /> : <MoonIcon />}
    </button>
  );
}

import { flushSync } from 'react-dom';

export type Theme = 'light' | 'dark';

export interface SiteThemeOptions {
  /** localStorage key for the visitor's explicit choice. */
  storageKey: string;
  /** Browser UI colour (<meta name="theme-color">) for each theme. */
  colors: { light: string; dark: string };
}

export interface SiteTheme {
  options: SiteThemeOptions;
  /** The theme on screen right now. Read from <html data-theme>. */
  get: () => Theme;
  /** Switches immediately, saves the choice and tells subscribers. */
  set: (theme: Theme) => void;
  subscribe: (listener: () => void) => () => void;
}

export function parseTheme(value: unknown): Theme | null {
  return value === 'light' || value === 'dark' ? value : null;
}

/**
 * One theme for the whole page. The document is the source of truth
 * (`<html data-theme>`), so every control on every route agrees, and a theme
 * change repaints through CSS without remounting anything.
 *
 * The choice is saved only when the visitor makes one. If storage is blocked
 * the switch still works for the current session. A choice made in another
 * tab is picked up through the `storage` event.
 */
export function createSiteTheme(options: SiteThemeOptions): SiteTheme {
  const listeners = new Set<() => void>();
  let watching = false;

  const get = (): Theme =>
    typeof document !== 'undefined' &&
    document.documentElement.dataset.theme === 'light'
      ? 'light'
      : 'dark';

  const paint = (theme: Theme) => {
    document.documentElement.dataset.theme = theme;
    document
      .querySelector('meta[name="theme-color"]')
      ?.setAttribute('content', options.colors[theme]);
  };

  const notify = () => {
    // Flush now, so a view transition captures the finished new state.
    try {
      flushSync(() => listeners.forEach((listener) => listener()));
    } catch {
      listeners.forEach((listener) => listener());
    }
  };

  const set = (theme: Theme) => {
    paint(theme);
    try {
      window.localStorage.setItem(options.storageKey, theme);
    } catch {
      // Storage can be blocked (private mode, policy). The session still works.
    }
    notify();
  };

  const onStorage = (event: StorageEvent) => {
    if (event.key !== options.storageKey) return;
    const theme = parseTheme(event.newValue);
    if (theme && theme !== get()) {
      paint(theme);
      notify();
    }
  };

  const subscribe = (listener: () => void) => {
    listeners.add(listener);
    if (!watching) {
      watching = true;
      window.addEventListener('storage', onStorage);
    }
    return () => {
      listeners.delete(listener);
      if (listeners.size === 0 && watching) {
        watching = false;
        window.removeEventListener('storage', onStorage);
      }
    };
  };

  return { options, get, set, subscribe };
}

